import 'package:flutter/material.dart';import 'package:flutter_riverpod/flutter_riverpod.dart';import '../../core/widgets/zaylo_widgets.dart';import '../../repositories/providers.dart';
class StudentsScreen extends ConsumerWidget{const StudentsScreen({super.key});@override Widget build(BuildContext context,WidgetRef ref)=>Scaffold(appBar:AppBar(title:const Text('Student Hub')),body:ListView(padding:const EdgeInsets.all(16),children:[for(final r in ref.watch(mockRepositoryProvider).studentResources()) ZayloCard(child:ListTile(title:Text(r.title),subtitle:Text('${r.category} • ${r.description}'))),...['Internships','Attachment opportunities','Student discussions','Saved resources'].map((x)=>ListTile(title:Text(x),onTap:()=>showComingSoon(context,x)))]));}
